_CUDA = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>
#include <algorithm>
#include <array>
#include <cstdint>

#define AC_CAT_I(a, b) a##b
#define AC_CAT(a, b) AC_CAT_I(a, b)

__global__ void prepare_batch_factor_and_pointers_kernel(
    const float* factor,
    float* diagonal,
    float* panel,
    int64_t* pointers,
    int size,
    int batch,
    long long factor_stride,
    long long factor_row_stride,
    long long factor_col_stride,
    long long diagonal_stride,
    long long diagonal_row_stride,
    long long panel_stride
) {
    __shared__ float tile[32][33];
    if (blockIdx.y > blockIdx.x) {
        return;
    }
    const int batch_index = static_cast<int>(blockIdx.z);
    const int factor_row = static_cast<int>(blockIdx.x) * 32 + threadIdx.x;
    const int factor_col_base = static_cast<int>(blockIdx.y) * 32 + threadIdx.y;
    for (int offset = 0; offset < 32; offset += 8) {
        const int factor_col = factor_col_base + offset;
        if (factor_row < size && factor_col < size
            && (blockIdx.x != blockIdx.y || factor_row >= factor_col)) {
            tile[threadIdx.y + offset][threadIdx.x] = factor[
                static_cast<long long>(batch_index) * factor_stride
                + static_cast<long long>(factor_row) * factor_row_stride
                + static_cast<long long>(factor_col) * factor_col_stride
            ];
        }
    }
    __syncthreads();

    const int diagonal_row = static_cast<int>(blockIdx.x) * 32 + threadIdx.y;
    const int diagonal_col_base =
        static_cast<int>(blockIdx.y) * 32 + threadIdx.x;
    for (int offset = 0; offset < 32; offset += 8) {
        if (diagonal_row + offset < size && diagonal_col_base < size
            && (blockIdx.x != blockIdx.y
                || diagonal_row + offset >= diagonal_col_base)) {
            diagonal[
                static_cast<long long>(batch_index) * diagonal_stride
                + static_cast<long long>(diagonal_row + offset)
                    * diagonal_row_stride
                + diagonal_col_base
            ] = tile[threadIdx.x][threadIdx.y + offset];
        }
    }

    if (blockIdx.x == 0 && blockIdx.y == 0
        && threadIdx.x == 0 && threadIdx.y == 0) {
        pointers[batch_index] = reinterpret_cast<int64_t>(
            factor + static_cast<long long>(batch_index) * factor_stride
        );
        pointers[batch + batch_index] = reinterpret_cast<int64_t>(
            panel + static_cast<long long>(batch_index) * panel_stride
        );
    }
}

void prepare_batch_factor_and_pointers_cuda(
    torch::Tensor factor,
    torch::Tensor diagonal,
    torch::Tensor panel,
    torch::Tensor pointers
) {
    const int batch = static_cast<int>(factor.size(0));
    TORCH_CHECK(
        factor.is_cuda() && diagonal.is_cuda() && panel.is_cuda()
        && pointers.is_cuda(),
        "CUDA tensors required"
    );
    TORCH_CHECK(
        factor.scalar_type() == torch::kFloat32
        && diagonal.scalar_type() == torch::kFloat32
        && panel.scalar_type() == torch::kFloat32
        && pointers.scalar_type() == torch::kInt64,
        "invalid preparation tensor types"
    );
    TORCH_CHECK(
        factor.dim() == 3 && diagonal.dim() == 3 && panel.dim() == 3
        && factor.sizes() == diagonal.sizes()
        && factor.size(0) == panel.size(0)
        && pointers.numel() == 2 * batch,
        "invalid preparation tensor shapes"
    );
    TORCH_CHECK(diagonal.stride(2) == 1, "diagonal columns must be contiguous");
    const int size = static_cast<int>(factor.size(1));
    const dim3 threads(32, 8);
    const dim3 blocks((size + 31) / 32, (size + 31) / 32, batch);
    prepare_batch_factor_and_pointers_kernel<<<
        blocks, threads, 0,
        c10::cuda::AC_CAT(getCurrentCUDA, AC_CAT(Str, eam))()
    >>>(
        factor.data_ptr<float>(),
        diagonal.data_ptr<float>(),
        panel.data_ptr<float>(),
        pointers.data_ptr<int64_t>(),
        size,
        batch,
        factor.stride(0),
        factor.stride(1),
        factor.stride(2),
        diagonal.stride(0),
        diagonal.stride(1),
        panel.stride(0)
    );
    C10_CUDA_KERNEL_LAUNCH_CHECK();
}

__global__ void convert_batch_panel_kernel(
    __half* __restrict__ converted,
    const float* __restrict__ source,
    long long group_count,
    int rows,
    int col_groups,
    long long converted_stride_0,
    long long converted_stride_1,
    long long source_stride_0,
    long long source_stride_1
) {
    const long long step =
        static_cast<long long>(gridDim.x) * blockDim.x;
    for (long long index =
             static_cast<long long>(blockIdx.x) * blockDim.x + threadIdx.x;
         index < group_count;
         index += step) {
        const int col_group = static_cast<int>(index % col_groups);
        const long long row_index = index / col_groups;
        const int row = static_cast<int>(row_index % rows);
        const long long batch = row_index / rows;
        const int col = col_group * 4;
        const float4 value = *reinterpret_cast<const float4*>(
            source + batch * source_stride_0 + row * source_stride_1 + col
        );
        __half2* packed = reinterpret_cast<__half2*>(
            converted
            + batch * converted_stride_0 + row * converted_stride_1 + col
        );
